import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../parcels/parcel_provider.dart';
Future<void> showCampaignResultForm(BuildContext context, WidgetRef ref, String campaignId) async {
 final kg=TextEditingController(),ha=TextEditingController(),marketable=TextEditingController(),quality=TextEditingController(),destination=TextEditingController(),notes=TextEditingController();
 await showDialog<void>(context:context,builder:(dialogContext)=>AlertDialog(title:const Text('Registrar resultado'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:kg,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Kg cosechados')),TextField(controller:ha,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Ha productivas')),TextField(controller:marketable,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Kg comercializables')),TextField(controller:quality,decoration:const InputDecoration(labelText:'Calidad')),TextField(controller:destination,decoration:const InputDecoration(labelText:'Destino')),TextField(controller:notes,decoration:const InputDecoration(labelText:'Notas'))])),actions:[TextButton(onPressed:()=>Navigator.pop(dialogContext),child:const Text('Cancelar')),FilledButton(onPressed:()async{final q=double.tryParse(kg.text),a=double.tryParse(ha.text);if(q==null||q<=0||a==null||a<=0)return;await ref.read(apiClientProvider).createCampaignResult(campaignId:campaignId,harvestedAt:DateTime.now(),harvestedQuantityKg:q,productiveAreaHa:a,marketableQuantityKg:double.tryParse(marketable.text),qualityGrade:quality.text.trim().isEmpty?null:quality.text.trim(),destination:destination.text.trim().isEmpty?null:destination.text.trim(),notes:notes.text.trim().isEmpty?null:notes.text.trim());if(dialogContext.mounted)Navigator.pop(dialogContext);},child:const Text('Guardar'))]));
}